import { AssistantRuntimeProvider, useLocalRuntime } from '@assistant-ui/react'
import { useQuery } from '@tanstack/react-query'
import { X } from 'lucide-react'
import { assistantStatusOptions } from '@/api/generated/@tanstack/react-query.gen'
import { Thread } from '@/components/assistant-ui/elements/thread.aui'
import { Button } from '@/components/ui/button'
import { TooltipProvider } from '@/components/ui/tooltip'
import { assistantAdapter } from '@/lib/assistantAdapter'

/**
 * Docked chat panel, toggled from the header.
 *
 * The chat UI under components/assistant-ui/ was generated by
 * `npx assistant-ui@latest add thread` and is yours to edit like shadcn components.
 */
export function AssistantPanel({ onClose }: { onClose: () => void }) {
  const runtime = useLocalRuntime(assistantAdapter)
  const status = useQuery(assistantStatusOptions())

  return (
    <aside className="flex h-full w-full flex-col border-l bg-background">
      <div className="flex items-center gap-2 border-b px-4 py-3">
        <span className="font-semibold">Assistant</span>
        {status.data && (
          <span className="text-xs text-muted-foreground">
            {status.data.configured ? status.data.model : 'no API key set'}
          </span>
        )}
        <Button variant="ghost" size="icon" className="ml-auto h-8 w-8" onClick={onClose} aria-label="Close assistant">
          <X className="h-4 w-4" />
        </Button>
      </div>

      {status.data && !status.data.configured && (
        <p className="border-b bg-amber-50 px-4 py-2 text-xs text-amber-900 dark:bg-amber-950 dark:text-amber-200">
          Set <code>OPENAI_API_KEY</code> in <code>backend/.env</code> and restart the API to enable chat.
        </p>
      )}

      <div className="min-h-0 flex-1">
        <AssistantRuntimeProvider runtime={runtime}>
          <TooltipProvider>
            <Thread />
          </TooltipProvider>
        </AssistantRuntimeProvider>
      </div>
    </aside>
  )
}
